const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, LevelFormat, WidthType, ShadingType,
  BorderStyle, Footer, PageNumber,
} = require("docx");

const OUT = process.argv[2];
const FONT = "Arial";
const INK = "1F2A37";
const ACCENT = "0F5C63";
const MUTED = "5B6770";
const TINT = "E8F1F2";
const WARN_TINT = "FBF1E3";
const WARN = "8A5A12";
const CONTENT_W = 9638;

const run = (text, o = {}) => new TextRun({ text, font: FONT, color: INK, ...o });

const h1 = (text) =>
  new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text, font: FONT })] });
const h2 = (text) =>
  new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text, font: FONT })] });

const p = (text, o = {}) =>
  new Paragraph({ spacing: { after: 100 }, children: [run(text, o)] });

const label = (text, color = ACCENT) =>
  new Paragraph({
    spacing: { before: 140, after: 60 },
    children: [run(text.toUpperCase(), { bold: true, size: 17, color, characterSpacing: 20 })],
  });

const item = (ref) => (lead, rest = "") =>
  new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { after: 50 },
    children: rest ? [run(lead, { bold: true }), run(" " + rest)] : [run(lead)],
  });
const check = item("checks");
const bullet = item("bullets");

const callout = (title, lines, tint, color) => [
  new Paragraph({
    spacing: { before: 160, after: 40 },
    shading: { type: ShadingType.CLEAR, fill: tint },
    border: { left: { style: BorderStyle.SINGLE, size: 18, color, space: 8 } },
    children: [run(title.toUpperCase(), { bold: true, size: 17, color, characterSpacing: 20 })],
  }),
  ...lines.map(
    (t, i) =>
      new Paragraph({
        spacing: { after: i === lines.length - 1 ? 160 : 30 },
        shading: { type: ShadingType.CLEAR, fill: tint },
        border: { left: { style: BorderStyle.SINGLE, size: 18, color, space: 8 } },
        children: [run(t)],
      })
  ),
];
const miss = (lines) => callout("Не упустить", lines, WARN_TINT, WARN);
const done = (line) => callout("Готово, когда", [line], TINT, ACCENT);

const cellBorder = { style: BorderStyle.SINGLE, size: 4, color: "C9D3D6" };
const borders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };
const table = (headers, rows, widths) =>
  new Table({
    width: { size: CONTENT_W, type: WidthType.DXA },
    columnWidths: widths,
    rows: [headers, ...rows].map(
      (cells, r) =>
        new TableRow({
          tableHeader: r === 0,
          children: cells.map(
            (text, c) =>
              new TableCell({
                borders,
                width: { size: widths[c], type: WidthType.DXA },
                margins: { top: 70, bottom: 70, left: 110, right: 110 },
                shading: r === 0 ? { type: ShadingType.CLEAR, fill: TINT } : undefined,
                children: [
                  new Paragraph({
                    children: [run(text, { bold: r === 0 || c === 0, size: 19, color: r === 0 ? ACCENT : INK })],
                  }),
                ],
              })
          ),
        })
    ),
  });
const gap = () => new Paragraph({ spacing: { after: 80 }, children: [] });

const body = [
  new Paragraph({
    spacing: { after: 60 },
    children: [run("Платформа управления коммуникациями", { bold: true, size: 40, color: ACCENT })],
  }),
  new Paragraph({
    spacing: { after: 240 },
    children: [run("Что собрать для ответа на задание. Рабочий план с отметками.", { size: 22, color: MUTED })],
  }),
  p("В каждом разделе три части. «Собрать» — пункты, которые должны появиться в ответе. «Не упустить» — места, где ответ обычно проседает. «Готово, когда» — признак, что раздел можно закрывать."),

  // ---------- 0
  h1("0. Основа ответа"),
  h2("0.1. Главный тезис"),
  label("Собрать"),
  check("Одна фраза.", "С чем вы спорите в текущем положении дел. Рабочая версия: внимание пользователя — общий ограниченный ресурс, и платформа распоряжается им по понятным правилам."),
  check("Два-три спорных решения.", "Для каждого — от чего вы отказались и почему."),
  ...done("Тезис можно сказать вслух за десять секунд, и с ним можно не согласиться."),

  h2("0.2. Вводные о задании"),
  label("Собрать"),
  check("Компания и её вертикали."),
  check("Формат и объём ответа:", "документ или презентация, сколько страниц."),
  check("Срок сдачи и кто проверяет."),
  check("Что значит «привлечение»:", "новые пользователи или привлечение существующих в новую вертикаль. Выбрать трактовку и назвать её."),

  h2("0.3. Допущения"),
  p("Писать только те, при изменении которых меняется решение. Пять-семь строк. К двум-трём дописать, что изменится, если допущение неверно."),
  table(
    ["Допущение", "На что влияет", "Ваша формулировка"],
    [
      ["Модель бизнеса и роли", "Сегменты, определение «ушедшего», единая мера ценности", ""],
      ["Текущая боль", "На какую проблему отвечает всё решение", ""],
      ["Что уже есть", "Строим с нуля или добавляем слой правил поверх готового", ""],
      ["Каналы и поверхности", "Состав MVP, цена отправки, лимиты", ""],
      ["Что оптимизирует компания", "Единая мера для сравнения сообщений", ""],
      ["Мандат", "Право ставить лимиты и останавливать чужие кампании", ""],
      ["Порядок масштаба", "Размер контрольной группы, нужна ли автоматика", ""],
    ],
    [2500, 3838, 3300]
  ),
  ...miss([
    "Не писать: стек и архитектуру, точные цифры выручки, описание каждой вертикали, обзор рынка, оргструктуру поимённо.",
  ]),

  // ---------- 1
  h1("1. Сегментация и управление коммуникациями"),
  h2("1.1. Сигналы и сегменты"),
  label("Собрать"),
  check("Слои сигналов:", "профиль и роль, этап жизни, свежее намерение, ценность, отклик на каналы и согласия, усталость."),
  check("Пять-восемь сегментов", "для разговора с бизнесом."),
  check("Определение «ушедшего»", "отдельно для вертикалей с разным циклом покупки."),
  check("Баланс спроса и предложения:", "кого будить в категории — покупателей или продавцов."),
  check("Настройки самого пользователя:", "выбор тем и частоты вместо «всё или ничего»."),
  check("Достижимость:", "до кого не дотянуться своими каналами и что с ними делать."),
  check("Чувствительность к скидке:", "кому бонус нужен, а кто купит и так."),
  check("Соседняя вертикаль:", "активен в одной, готов к другой."),
  check("Стоп-сигналы:", "обращение в поддержку, жалоба, спор по сделке."),
  check("Контекст момента:", "человек сейчас в приложении, ночные часы."),
  check("Новички и неавторизованные:", "правила по умолчанию, когда истории нет."),
  check("Свежесть данных:", "что обновляется за минуты, а что раз в сутки."),
  ...miss([
    "Сегменты и личные оценки — разные вещи. Сегменты нужны для разговора с бизнесом. Решение по человеку принимается по его оценкам.",
    "Один человек может быть и покупателем, и продавцом.",
  ]),

  h2("1.2. Типы сообщений"),
  table(
    ["Тип", "Пример", "Правило"],
    [
      ["Сервисные", "Код, статус сделки, безопасность", "Всегда, вне лимитов"],
      ["От другого человека", "Сообщение в чате, отклик, отзыв", "Вне лимитов, можно склеивать"],
      ["Триггерные", "Брошенный поиск, упала цена в избранном", "Конкурируют, живут часы"],
      ["По этапу жизни", "Первые шаги новичка, возврат ушедших", "Конкурируют, можно отложить"],
      ["Промо", "Акция, распродажа", "Жёсткий лимит, нужно согласие на рекламу"],
      ["Продажа платных услуг", "Продвижение объявления, тариф для продавца", "Как промо, но для другой роли"],
      ["Подборки и контент", "Дайджест, рекомендации", "Низкий приоритет"],
      ["Продуктовые", "Новая функция", "Низкий приоритет"],
      ["Опросы", "Оценка сервиса", "Идут в общий лимит"],
      ["Обязательные", "Изменение условий", "Всегда, редко"],
    ],
    [2500, 3838, 3300]
  ),
  label("Собрать"),
  check("Оси вместо списка:", "кто инициатор, ждёт ли пользователь сообщение, сколько оно живёт, можно ли отложить или склеить, реклама ли это по закону."),
  check("Кто присваивает тип.", "Платформа, а не заказчик."),
  ...miss(["Вертикали будут выдавать промо за триггер или сервисное сообщение, чтобы обойти лимит."]),

  h2("1.3. Механизм решения"),
  label("Собрать"),
  check("Схема из шести шагов:", "жёсткие фильтры, список кандидатов, оценка, выбор победителя или молчание, канал и время, запись результата."),
  check("Список жёстких правил:", "согласия, закон, лимиты, стоп-сигналы, тихие часы."),
  check("Формула оценки:", "вероятность действия × ценность действия × доля, которой без сообщения не случилось бы, минус цена канала, штраф за усталость и риск отписки."),
  check("Откуда берётся каждое число в первой версии:", "таблица экспертных оценок, историческая конверсия."),
  check("Исход «не отправлять ничего»", "как полноправный вариант."),
  check("Правило выбора канала и времени."),
  check("Путь развития одной строкой:", "правила, простые оценки, модели."),
  ...miss([
    "Формула описывает целевое состояние. Первая версия — правила и простые оценки. Противоречия между ними быть не должно.",
    "Отписка стоит дорого: канал теряется на будущее. Это должно быть в формуле.",
  ]),

  h2("1.4. Конкуренция вертикалей и маркетинга"),
  label("Собрать"),
  check("Единая мера ценности", "и её слабое место: крупная вертикаль с деньгами выигрывает всегда."),
  check("Классы приоритета."),
  check("Гарантированные доли", "для маленьких и стратегических вертикалей."),
  check("Стратегические веса", "и кто их утверждает."),
  check("Небольшой бюджет на пробы", "для новых сценариев без истории."),
  check("Сверка заявленной ценности с фактом,", "чтобы заказчики её не завышали."),

  h2("1.5. Усталость и риск негативной реакции"),
  label("Собрать"),
  check("Лимиты:", "общий на человека и отдельные по каналам."),
  check("Пауза после сообщения", "и после отрицательного сигнала."),
  check("Класс риска у сообщения:", "неуместный момент, слишком личная персонализация, ошибка адресата."),
  check("Поверхности внутри приложения:", "своя логика — человека не прерывают, но мест мало."),
  check("Качество самих сообщений:", "стандарты текста и шаблонов."),

  h2("1.6. Разобранный пример"),
  label("Собрать"),
  check("Один пользователь, три претендента", "от разных заказчиков. Кто победил, кто отложен, кто отклонён и почему."),
  ...done("По вашей схеме можно вручную решить пример и получить тот же ответ."),

  // ---------- 2
  h1("2. Метрики и аналитика"),
  h2("2.1. Метрики управления"),
  label("Собрать"),
  check("Главная:", "добавленная ценность на пользователя."),
  check("Воронка канала:", "доставка, открытие, действие."),
  check("Здоровье базы:", "отписки, отключение пушей, жалобы, удаление приложения, размер достижимой базы."),
  check("Сама платформа:", "доля сообщений через неё, скорость запуска кампании."),

  h2("2.2. Добавленный эффект"),
  label("Собрать"),
  check("Общая долгая контрольная группа:", "размер, что она получает, как обновляется."),
  check("Контроль на уровне кампании."),
  check("Тест самой логики выбора."),
  check("Раздельный замер", "для выручки, целевых действий и удержания."),
  check("Удержание на 30, 60 и 90 дней."),
  check("Как отвечать на спор", "о «потерянной выручке» контрольной группы."),
  ...miss([
    "Клики и «последнее касание» не доказывают эффект. Сказать это прямо.",
    "Сообщения отнимают действия друг у друга и у органики.",
    "На двусторонней площадке группы влияют друг на друга. Разбудили продавцов — это почувствовали покупатели из контроля.",
    "Малые эффекты требуют месяцев. Не обещать доказательство раньше, чем оно возможно.",
  ]),

  h2("2.3. Защитные метрики"),
  label("Собрать"),
  check("Список метрик с порогами."),
  check("Автоматическая остановка", "при превышении порога."),
  check("Парная цель:", "отписки вниз, добавленная ценность не падает."),
  ...done("Метрики из этого блока стоят в формуле блока 1 и в целях блока 4."),

  // ---------- 3
  h1("3. Модель взаимодействия"),
  h2("3.1. Что в центре, что у команд"),
  label("Собрать"),
  check("В центре:", "правила выбора, лимиты, согласия, методика измерения, инфраструктура каналов, стандарты, классификация типов."),
  check("У вертикалей и маркетинга:", "гипотезы, контент, бизнес-цель и результат."),

  h2("3.2. Кто за что отвечает"),
  table(
    ["Зона", "Кто отвечает", "Ваше уточнение"],
    [
      ["Аудитория, единый профиль", "Платформа", ""],
      ["Контент", "Заказчик, в рамках стандартов", ""],
      ["Бизнес-результат", "Заказчик", ""],
      ["Пользовательские ограничения", "Платформа, с правом остановки", ""],
    ],
    [3200, 3438, 3000]
  ),

  h2("3.3. Приоритеты и конфликты"),
  label("Собрать"),
  check("Правила и оценка ценности", "вместо ручной очереди."),
  check("Комитет только для исключений", "и путь эскалации."),
  check("Прозрачность:", "заказчик видит, почему его сообщение не ушло."),
  check("Раздел поверхностей внутри приложения", "между заказчиками."),
  ...miss([
    "Зачем это вертикалям: честное доказательство эффекта и быстрый запуск. Без выгоды они не отдадут контроль.",
    "Откуда берётся право остановки и кто стоит над спором.",
    "У вас свой KPI по удержанию. Вы одновременно судья и игрок. Показать, как это разведено.",
  ]),
  ...done("На любой спор двух заказчиков есть ответ без вашего личного участия."),

  // ---------- 4
  h1("4. MVP и план запуска"),
  h2("4.1. Состав"),
  label("Собрать"),
