const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, LevelFormat, WidthType, ShadingType,
  BorderStyle, Footer, PageNumber,
} = require("docx");

const OUT = process.argv[2];
const FONT = "Arial";
const INK = "1F2A37";
const ACCENT = "0F5C63";
const MUTED = "5B6770";
const TINT = "E8F1F2";
const WARN_TINT = "FBF1E3";
const WARN = "8A5A12";
const CONTENT_W = 9638;

const run = (text, o = {}) => new TextRun({ text, font: FONT, color: INK, ...o });

const h1 = (text) =>
  new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text, font: FONT })] });
const h2 = (text) =>
  new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text, font: FONT })] });

const p = (text, o = {}) =>
  new Paragraph({ spacing: { after: 100 }, children: [run(text, o)] });

const label = (text, color = ACCENT) =>
  new Paragraph({
    spacing: { before: 140, after: 60 },
    children: [run(text.toUpperCase(), { bold: true, size: 17, color, characterSpacing: 20 })],
  });

const item = (ref) => (lead, rest = "") =>
  new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { after: 50 },
    children: rest ? [run(lead, { bold: true }), run(" " + rest)] : [run(lead)],
  });
const check = item("checks");
const bullet = item("bullets");

const callout = (title, lines, tint, color) => [
  new Paragraph({
    spacing: { before: 160, after: 40 },
    shading: { type: ShadingType.CLEAR, fill: tint },
    border: { left: { style: BorderStyle.SINGLE, size: 18, color, space: 8 } },
    children: [run(title.toUpperCase(), { bold: true, size: 17, color, characterSpacing: 20 })],
  }),
  ...lines.map(
    (t, i) =>
      new Paragraph({
        spacing: { after: i === lines.length - 1 ? 160 : 30 },
        shading: { type: ShadingType.CLEAR, fill: tint },
        border: { left: { style: BorderStyle.SINGLE, size: 18, color, space: 8 } },
        children: [run(t)],
      })
  ),
];
const miss = (lines) => callout("Не упустить", lines, WARN_TINT, WARN);
const done = (line) => callout("Готово, когда", [line], TINT, ACCENT);

const cellBorder = { style: BorderStyle.SINGLE, size: 4, color: "C9D3D6" };
const borders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };
const table = (headers, rows, widths) =>
  new Table({
    width: { size: CONTENT_W, type: WidthType.DXA },
    columnWidths: widths,
    rows: [headers, ...rows].map(
      (cells, r) =>
        new TableRow({
          tableHeader: r === 0,
          children: cells.map(
            (text, c) =>
              new TableCell({
                borders,
                width: { size: widths[c], type: WidthType.DXA },
                margins: { top: 70, bottom: 70, left: 110, right: 110 },
                shading: r === 0 ? { type: ShadingType.CLEAR, fill: TINT } : undefined,
                children: [
                  new Paragraph({
                    children: [run(text, { bold: r === 0 || c === 0, size: 19, color: r === 0 ? ACCENT : INK })],
                  }),
                ],
              })
          ),
        })
    ),
  });
const gap = () => new Paragraph({ spacing: { after: 80 }, children: [] });

const body = [
  new Paragraph({
    spacing: { after: 60 },
    children: [run("Платформа управления коммуникациями", { bold: true, size: 40, color: ACCENT })],
  }),
  new Paragraph({
    spacing: { after: 240 },
    children: [run("Что собрать для ответа на задание. Рабочий план с отметками.", { size: 22, color: MUTED })],
  }),
  p("В каждом разделе три части. «Собрать» — пункты, которые должны появиться в ответе. «Не упустить» — места, где ответ обычно проседает. «Готово, когда» — признак, что раздел можно закрывать."),

  // ---------- 0
  h1("0. Основа ответа"),
  h2("0.1. Главный тезис"),
  label("Собрать"),
  check("Одна фраза.", "С чем вы спорите в текущем положении дел. Рабочая версия: внимание пользователя — общий ограниченный ресурс, и платформа распоряжается им по понятным правилам."),
  check("Два-три спорных решения.", "Для каждого — от чего вы отказались и почему."),
  ...done("Тезис можно сказать вслух за десять секунд, и с ним можно не согласиться."),

  h2("0.2. Вводные о задании"),
