  h2("1.2. Типы сообщений"),
  table(
    ["Тип", "Пример", "Правило"],
    [
      ["Сервисные", "Код, статус сделки, безопасность", "Всегда, вне лимитов"],
      ["От другого человека", "Сообщение в чате, отклик, отзыв", "Вне лимитов, можно склеивать"],
      ["Триггерные", "Брошенный поиск, упала цена в избранном", "Конкурируют, живут часы"],
