const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, LevelFormat, WidthType, ShadingType,
  BorderStyle, Footer, PageNumber,
} = require("docx");

const OUT = process.argv[2];
const FONT = "Arial";
const INK = "1F2A37";
const ACCENT = "0F5C63";
const MUTED = "5B6770";
const TINT = "E8F1F2";
const WARN_TINT = "FBF1E3";
const WARN = "8A5A12";
const CONTENT_W = 9638;

const run = (text, o = {}) => new TextRun({ text, font: FONT, color: INK, ...o });

const h1 = (text) =>
  new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text, font: FONT })] });
const h2 = (text) =>
  new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text, font: FONT })] });

const p = (text, o = {}) =>
  new Paragraph({ spacing: { after: 100 }, children: [run(text, o)] });

const label = (text, color = ACCENT) =>
  new Paragraph({
    spacing: { before: 140, after: 60 },
    children: [run(text.toUpperCase(), { bold: true, size: 17, color, characterSpacing: 20 })],
  });

const item = (ref) => (lead, rest = "") =>
  new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { after: 50 },
    children: rest ? [run(lead, { bold: true }), run(" " + rest)] : [run(lead)],
  });
const check = item("checks");
const bullet = item("bullets");

const callout = (title, lines, tint, color) => [
  new Paragraph({
    spacing: { before: 160, after: 40 },
    shading: { type: ShadingType.CLEAR, fill: tint },
    border: { left: { style: BorderStyle.SINGLE, size: 18, color, space: 8 } },
    children: [run(title.toUpperCase(), { bold: true, size: 17, color, characterSpacing: 20 })],
  }),
  ...lines.map(
    (t, i) =>
      new Paragraph({
        spacing: { after: i === lines.length - 1 ? 160 : 30 },
        shading: { type: ShadingType.CLEAR, fill: tint },
        border: { left: { style: BorderStyle.SINGLE, size: 18, color, space: 8 } },
        children: [run(t)],
      })
